[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles',[string]$OutputPath='')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$dir=[IO.Path]::GetFullPath((Join-Path $root $BundlesDirectory));if(-not $dir.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'BundlesDirectory must remain under project root.'};$validator=Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioOfflinePackage.ps1';$rows=[System.Collections.Generic.List[object]]::new();foreach($d in @(Get-ChildItem -LiteralPath $dir -Directory -Filter '*-offline')){$r=& $validator -PackageDirectory $d.FullName|ConvertFrom-Json;$rows.Add([pscustomobject]@{package=$d.Name;status=$r.status;checkCount=$r.checkCount;passedCount=$r.passedCount;failedCount=$r.failedCount;registerType=$r.registerType})};$passed=@($rows|? status -eq 'passed').Count;$failed=$rows.Count-$passed;$report=[pscustomobject]@{schemaVersion=1;recordType='WebPageStudioAllOfflinePackagesReceipt';status=if($failed -eq 0 -and $rows.Count -gt 0){'passed'}else{'partial'};packageCount=$rows.Count;passedPackageCount=$passed;failedPackageCount=$failed;packages=$rows;evidenceLevel='S1';runtimeStatus='runtime-not-run';claimsNotProven=@('Batch offline validation does not prove browser Service Worker installation or production HTTPS behavior.')};if($OutputPath){$out=[IO.Path]::GetFullPath((Join-Path $root $OutputPath));if(-not $out.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'OutputPath must remain under project root.'};[IO.File]::WriteAllText($out,($report|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))};$report|ConvertTo-Json -Depth 10
